{
  "title": "Checkout error rate",
  "type": "timeseries",
  "targets": [
    { "expr": "sum(rate(checkout_requests_total{status=~\"5..\"}[5m])) / sum(rate(checkout_requests_total[5m]))" }
  ],
  "fieldConfig": {
    "defaults": {
      "unit": "percentunit",
      "thresholds": {
        "steps": [
          { "color": "green", "value": 0 },
          { "color": "orange", "value": 0.01 },
          { "color": "red", "value": 0.05 }
        ]
      }
    }
  }
}
